import{_ as a,c as t,o,ag as r}from"./chunks/framework.BXxQSk_p.js";const h=JSON.parse('{"title":"Project-Control Gate Spec","description":"","frontmatter":{},"headers":[],"relativePath":"specs/project-control-gate.md","filePath":"specs/project-control-gate.md"}'),c={name:"specs/project-control-gate.md"};function i(n,e,l,s,d,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="project-control-gate-spec" tabindex="-1">Project-Control Gate Spec <a class="header-anchor" href="#project-control-gate-spec" aria-label="Permalink to &quot;Project-Control Gate Spec&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Validate WebGPU&#39;s project-control and GroundAtlas adoption surfaces without changing native WebGPU behavior, package exports, platform native artifacts, runtime tests, release artifacts, or compatibility claims.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The gate validates repository control-plane facts only:</p><ul><li>neutral identity and truth homes live in <code>project.manifest.json</code>;</li><li>Sylphx-specific governance facts remain in <code>.doctrine/project.json</code>;</li><li>generated <code>.groundatlas*</code> outputs are evidence/navigation only;</li><li>native package release proof remains CI, native artifact evidence, Release workflow completion, <code>release:readback</code>, and npm registry readback;</li><li>GPU runtime and compatibility claims still require native tests or documented compatibility evidence before behavior/claim changes.</li></ul><p>It does not own consumer rendering policy, shader assets, GPU scheduling policy, upstream wgpu behavior, browser WebGPU behavior, platform driver bugs, or shared organization rulesets.</p><h2 id="ci-contract" tabindex="-1">CI Contract <a class="header-anchor" href="#ci-contract" aria-label="Permalink to &quot;CI Contract&quot;">​</a></h2><p><code>.github/workflows/ci.yml</code> must:</p><ol><li>run a single <code>groundatlas</code> job before the native build matrix;</li><li>run <code>node --test test/project-control.node-test.mjs</code>;</li><li>run <code>SylphxAI/groundatlas@v0.1.2</code> with <code>package-spec: groundatlas@0.1.2</code>, <code>require-atlas: &quot;true&quot;</code>, and <code>strict: &quot;true&quot;</code>;</li><li>assert that GroundAtlas selects <code>project.manifest.json</code> and treats <code>.doctrine/project.json</code> only as an adapter;</li><li>upload the manifest and fleet reports as <code>groundatlas-package-dogfood</code>;</li><li>keep the native build matrix gated through <code>needs: groundatlas</code> and an explicit failure step when the GroundAtlas job is not successful.</li></ol><h2 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h2><ul><li><code>ga audit</code> passes after <code>ga update</code>.</li><li><code>ga manifest --json</code> selects <code>project.manifest.json</code>.</li><li><code>ga fleet --require-atlas --strict --json</code> reports one adopted project with zero warnings and zero blockers.</li><li>Native build matrix jobs depend on the GroundAtlas gate.</li><li>Existing CI, Tests, Release, and <code>release:readback</code> package boundaries remain the release proof for changed native packages.</li></ul>',12)])])}const g=a(c,[["render",i]]);export{h as __pageData,g as default};
